<?php
$zipData = base64_decode('');
file_put_contents('deploy_sidebar_fix.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_sidebar_fix.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_sidebar_fix.zip');
    echo '<h1>Dynamic Sidebar Bug Fixed! Waiter can now access all checked pages!</h1>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>